versions.variantCss:
.wemd-copyright-notice[data-variant="bytedance-copyright"] {
  background: var(--wemd-bg-soft);
  border-radius: var(--wemd-border-radius);
  padding: 16px 20px;
  margin: 24px 0;
  text-align: center;
  border-top: 2px solid var(--wemd-primary);
}
.wemd-copyright-notice[data-variant="bytedance-copyright"] .wemd-component-body {
  padding: 0;
}
.wemd-copyright-notice[data-variant="bytedance-copyright"] .wemd-component-body .wemd-child-1 {
  color: var(--wemd-primary);
  font-size: 14px;
  font-weight: 700;
  margin: 0 0 4px 0;
}
.wemd-copyright-notice[data-variant="bytedance-copyright"] .wemd-component-body .wemd-child-2 {
  color: var(--wemd-text-soft);
  font-size: 12px;
  line-height: 1.6;
  margin: 0;
}
